insert into public.flashcards (id, set_slug, week, track, front, back, source, visual) values ('cs-doji-adults', 'candlestick-patterns', null, 'adults', 'Which candlestick pattern is shown?', 'Open and close are nearly equal — buyers and sellers finished even. Signals indecision and a possible turning point, especially after a strong move.', 'Indecision', '{"name":"Doji","candles":[{"o":100,"h":103.2,"l":96.8,"c":100.1}]}'::jsonb) on conflict (id) do nothing;
